/* Scroll reveals driven by the view timeline of the element itself. Without support for
   animation-timeline (or with reduced motion) the content simply sits in place. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .zetta-joule-rise {
      animation: zetta-joule-reveal-rise linear both;
      animation-timeline: view();
      animation-range: entry 0% entry 70%;
    }
    /* a block of text: rises 30px and uncovers top to bottom, standing in for per-line staggering */
    .zetta-joule-lines {
      animation: zetta-joule-reveal-lines linear both;
      animation-timeline: view();
      animation-range: entry 0% cover 38%;
      -webkit-mask-image: linear-gradient(to bottom, var(--foreground) 0%, var(--foreground) 33%, transparent 66%, transparent 100%);
      mask-image: linear-gradient(to bottom, var(--foreground) 0%, var(--foreground) 33%, transparent 66%, transparent 100%);
      -webkit-mask-size: 100% 300%;
      mask-size: 100% 300%;
      -webkit-mask-repeat: no-repeat;
      mask-repeat: no-repeat;
    }
  }
}

@keyframes zetta-joule-reveal-rise {
  from { opacity: 0; transform: translateY(var(--zetta-joule-rise, 16px)); }
  to { opacity: 1; transform: none; }
}

@keyframes zetta-joule-reveal-lines {
  from {
    opacity: 0;
    transform: translateY(var(--zetta-joule-rise, 30px));
    -webkit-mask-position: 0 100%;
    mask-position: 0 100%;
  }
  to {
    opacity: 1;
    transform: none;
    -webkit-mask-position: 0 0;
    mask-position: 0 0;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./zetta-joule-reveal.css";

export interface ZettaJouleRevealProps {
  /** rise: fade in and lift 16px (buttons, cards); lines: a text block that lifts 30px and uncovers top to bottom */
  variant?: "rise" | "lines";
  /** how far it lifts, in px (default 16 for rise, 30 for lines) */
  distance?: number;
  /** the tag to render */
  as?: ElementType;
  children: ReactNode;
  className?: string;
}

/** Wraps content so it reveals while it scrolls into view (CSS scroll-driven animation, no JavaScript). */
export function ZettaJouleReveal({ variant = "rise", distance, as: Tag = "div", children, className }: ZettaJouleRevealProps) {
  const style = distance ? ({ "--zetta-joule-rise": `${distance}px` } as CSSProperties) : undefined;
  return (
    <Tag className={cn(variant === "lines" ? "zetta-joule-lines" : "zetta-joule-rise", className)} style={style}>
      {children}
    </Tag>
  );
}
